/**
 * KeyVEX app logo — shield + key on a glass / 3D rounded tile, one colourway per theme.
 * Pure string builders (no DOM) so the same artwork is used by the login screen, the browser-tab icon,
 * and the installable-app icons generated by `scripts/gen-icons.mjs`.
 */

/** [top, middle, bottom, tint] — same gradient stops as the page theme (`--l1 --l2 --l3 --tint`). */
export const LOGO_COLORS = {
  ocean: ["#5ee0d2", "#2a86f0", "#1349b3", "#c9ecff"],
  sunset: ["#ffb347", "#ff6a3d", "#e0301e", "#ffd9b8"],
  violet: ["#b266ff", "#8a2eff", "#4b12b8", "#e5ccff"],
  light: ["#fb923c", "#ea580c", "#9a3412", "#fed7aa"]
};

/** Dark page background per theme (PWA splash / theme-color). */
export const THEME_BG = {
  ocean: "#081428",
  sunset: "#1c0a0c",
  violet: "#0e081e",
  light: "#1a0b08"
};

export const LOGO_THEMES = Object.keys(LOGO_COLORS);

const SHIELD = "M96 38 L54 54 V86 C54 113 71 131 96 143 C121 131 138 113 138 86 V54 Z";

/**
 * @param {string} theme  ocean | sunset | violet | light
 * @param {object} o
 * @param {string}  [o.id]       unique id prefix (several logos can live on one page)
 * @param {boolean} [o.rounded]  true: rounded tile with transparent corners; false: full-bleed square (maskable / iOS)
 * @param {number}  [o.scale]    shield scale around the centre (maskable icons keep the art inside the safe zone)
 * @param {boolean} [o.xmlns]    include the xmlns attribute (standalone files / data URLs)
 * @param {boolean} [o.vars]     colour the tile with the page's CSS variables (--l1/--l2/--l3/--tint) so it follows the theme live
 */
export function logoSvg(theme = "ocean", { id = "kv", rounded = true, scale = 1, xmlns = true, vars = false } = {}) {
  const [c1, c2, c3, tint] = LOGO_COLORS[theme] || LOGO_COLORS.ocean;
  const r = rounded ? 44 : 0;
  const tile = rounded
    ? `<rect x="0" y="0" width="192" height="192" rx="${r}"/>`
    : `<rect x="0" y="0" width="192" height="192"/>`;
  const rim = rounded
    ? `<rect x="2" y="2" width="188" height="188" rx="${r - 2}" fill="none" stroke="url(#${id}-rim)" stroke-width="3"/>`
    : "";
  const t = scale === 1 ? "" : ` transform="translate(96 96) scale(${scale}) translate(-96 -96)"`;
  const out = `<svg ${xmlns ? 'xmlns="http://www.w3.org/2000/svg" ' : ""}viewBox="0 0 192 192"><defs>`
    + `<linearGradient id="${id}-bg" x1=".12" y1="0" x2=".88" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset=".55" stop-color="${c2}"/><stop offset="1" stop-color="${c3}"/></linearGradient>`
    + `<radialGradient id="${id}-glow" cx=".28" cy=".12" r=".75"><stop offset="0" stop-color="#fff" stop-opacity=".6"/><stop offset=".55" stop-color="#fff" stop-opacity=".08"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>`
    + `<linearGradient id="${id}-gloss" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".5"/><stop offset="1" stop-color="#fff" stop-opacity=".04"/></linearGradient>`
    + `<linearGradient id="${id}-shade" x1="0" y1="0" x2="0" y2="1"><stop offset=".55" stop-color="#000a24" stop-opacity="0"/><stop offset="1" stop-color="#000a24" stop-opacity=".38"/></linearGradient>`
    + `<linearGradient id="${id}-rim" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".85"/><stop offset=".5" stop-color="#fff" stop-opacity=".08"/><stop offset="1" stop-color="#fff" stop-opacity=".4"/></linearGradient>`
    + `<linearGradient id="${id}-sh" x1=".2" y1="0" x2=".8" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".6" stop-color="#fff"/><stop offset="1" stop-color="${tint}"/></linearGradient>`
    + `<linearGradient id="${id}-shgl" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".95"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>`
    + `<linearGradient id="${id}-key" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${c2}"/><stop offset="1" stop-color="${c3}"/></linearGradient>`
    + `<filter id="${id}-drop" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="7" stdDeviation="6" flood-color="#000a24" flood-opacity=".42"/></filter>`
    + `<clipPath id="${id}-clip">${tile}</clipPath>`
    + `</defs>`
    // tile: colour + glass sheen + soft bottom shade (3D) + rim light
    + `<g clip-path="url(#${id}-clip)">`
    + `<rect width="192" height="192" fill="url(#${id}-bg)"/>`
    + `<rect width="192" height="192" fill="url(#${id}-glow)"/>`
    + `<path d="M-10 -10H202V92C160 112 120 76 96 82 64 90 30 118 -10 96Z" fill="url(#${id}-gloss)" opacity=".55"/>`
    + `<rect width="192" height="192" fill="url(#${id}-shade)"/>`
    + `</g>${rim}`
    // shield + keyhole
    + `<g${t}>`
    + `<g filter="url(#${id}-drop)"><path d="${SHIELD}" fill="url(#${id}-sh)" stroke="url(#${id}-sh)" stroke-width="8" stroke-linejoin="round"/></g>`
    + `<path d="M96 44 L60 58 V86 C60 106 70 120 82 130 70 112 68 90 72 70 76 58 86 50 96 44Z" fill="url(#${id}-shgl)" opacity=".7"/>`
    + `<circle cx="96" cy="80" r="13.5" fill="url(#${id}-key)"/>`
    + `<path d="M92 90H100V122Q100 125 96 125 92 125 92 122Z M99 106H110V113H99Z M99 116H107V122H99Z" fill="url(#${id}-key)"/>`
    + `<circle cx="91.5" cy="75" r="4" fill="#fff" opacity=".35"/>`
    + `</g></svg>`;
  if (!vars) return out;
  return [[c1, "--l1"], [c2, "--l2"], [c3, "--l3"], [tint, "--tint"]]
    .reduce((acc, [hex, v]) => acc.replaceAll(`stop-color="${hex}"`, `style="stop-color:var(${v})"`), out);
}

export const themeBg = (theme) => THEME_BG[theme] || THEME_BG.ocean;
